INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (1,31,1,'primary','The CEO is trapped by sunk cost fallacy — the $1.2M and 14 months are gone regardless.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (2,31,9,'secondary','Every month on the struggling product is a month not spent on the churn-prediction opportunity.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (3,32,7,'primary','The founder overestimates continued success because the viral moment is recent and vivid.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (4,32,3,'secondary','The CFO is correctly tracing downstream consequences of overcommitting based on a temporary spike.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (5,33,6,'primary','Interviewers formed opinions early and confirmed them throughout the process.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (6,33,5,'secondary','The 40% success rate for external VP hires is being overridden by the vivid interview narrative.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (7,34,6,'primary','Research was commissioned to support a predetermined conclusion, not genuinely evaluate.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (8,34,9,'secondary','The $3M alternative — deepening European market share — was never evaluated.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (9,35,9,'primary','Every sprint shipping new features is a sprint NOT fixing UX, reducing complexity, or addressing churn.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (10,35,6,'secondary','VP selectively cites survey data supporting shipping velocity while dismissing NPS as lagging.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (11,36,1,'primary','CEO cannot let go because of 5 years invested — those years are gone regardless.');
INSERT INTO `tr_scenario_correct_models` (`id`, `scenario_id`, `model_id`, `rank_level`, `relevance_note`) VALUES (12,36,8,'secondary','The $30M figure anchors all thinking about company value. Board member applies inversion to remove it.');
